		clusters: []coreapi.Cluster{expertsTestCluster()},
		repo:     &coreapi.Repo{ID: expertsTestRepoULID, ClusterHost: coreapi.NewOptString(expertsTestClusterHost)},
	}
	withFakeCellCore(t, f)
	return f
}

