func (f *fakeExpertsClient) Post(_ context.Context, path string, body any) (*http.Response, error) {
	f.gotPath = path
	f.gotBody = body
	status := f.status
	if status == 0 {
		status = http.StatusOK
	}
	return &http.Response{
		StatusCode: status,
		Body:       io.NopCloser(strings.NewReader(f.body)),
	}, nil
}

